 "nctId": "NCT06693895",
 "briefTitle": "A Study on the Safety of an Investigational Chickenpox Vaccine, When Given to Healthy Children, 12 to 15 Months of Age",
 "officialTitle": "A Phase 3a, Observer-blind, Randomized, Controlled Study to Evaluate the Safety of an Investigational Varicella Vaccine Compared With Varivax, Administered as a First Dose to Healthy Children 12 to 15 Months of Age",
 "leadSponsor": {
  "name": "GlaxoSmithKline",
