    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 750,
 "briefSummary": "The purpose of this study is to assess how well-tolerated GSK's investigational varicella vaccine (VNS Vaccine) is, in comparison to an already approved varicella vaccine (VV) known as Varivax. The study will be conducted on healthy children aged 12 to 15 months, and who have neither contracted varicella nor received a varicella vaccination.",
 "arms": [
  {
   "label": "VNS Group",
   "type": "EXPERIMENTAL",
   "description": "Participants receive 1 dose of a VNS vaccine, 1 dose of measles, mumps, and rubella (MMR) vaccine, 1 dose of hepatitis A (HAV) vaccine, and 1 dose of PCV (either PCV 13 or Vaxneuvance or PCV 20) on Day 1.",
   "interventionNames": [
    "Biological: Investigational varicella vaccine",
    "Biological: Measles, mumps, and rubella vaccine",
    "Biological: Hepatitis A vaccine",
    "Biological: PCV (pneumococcal conjugate vaccine) 13",
    "Biological: PCV 20",
    "Biological: Vaxneuvance"
   ]
  },
  {
   "label": "VV Group",
   "type": "ACTIVE_COMPARATOR",
   "description": "Participants receive 1 dose of a marketed VV, 1 dose of MMR vaccine, 1 dose of HAV vaccine, and 1 dose of PCV (either PCV 13 or Vaxneuvance or PCV 20) on Day 1.",
   "interventionNames": [
    "Biological: Marketed varicella vaccine",
    "Biological: Measles, mumps, and rubella vaccine",
    "Biological: Hepatitis A vaccine",
    "Biological: PCV (pneumococcal conjugate vaccine) 13",
    "Biological: PCV 20",
    "Biological: Vaxneuvance"
   ]
  }
 ],
 "interventions": [
