   ]
  },
  {
   "type": "BIOLOGICAL",
   "name": "Measles, mumps, and rubella vaccine",
   "description": "1 dose of measles, mumps, and rubella vaccine co-administered subcutaneously or intramuscularly.",
   "armGroupLabels": [
    "VNS Group",
    "VV Group"
   ]
  },
  {
