   "armGroupLabels": [
    "VNS Group",
    "VV Group"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Percentage of participants reporting each solicited administration site events",
   "description": "Solicited administration site events include injection site redness, pain and swelling.",
   "timeFrame": "Day 1 (post-dose) to Day 4"
  },
  {
   "measure": "Percentage of participants reporting each solicited systemic event",
   "description": "Solicited systemic events include drowsiness, loss of appetite and irritability.",
   "timeFrame": "Day 1 (post-dose) to Day 15"
  },
  {
   "measure": "Percentage of participants reporting each solicited systemic event in terms of fever",
   "description": "Fever is defined as temperature greater than or equal to (\\>=) 38.0°C (100.4°F) by any route (the preferred location for measuring temperature is the axilla).",
   "timeFrame": "Day 1 (post-dose) to Day 22"
  },
  {
   "measure": "Percentage of participants reporting each solicited administration site events",
   "description": "Solicited administration site include injection site varicella-like rash.",
   "timeFrame": "Day 1 (post-dose) to Day 43"
  },
  {
   "measure": "Percentage of participants reporting solicited systemic events",
   "description": "Solicited systemic events includes varicella-like rash (non-injection site), and general rash (not varicella-like).",
   "timeFrame": "Day 1 (post-dose) to Day 43"
  },
  {
   "measure": "Percentage of participants reporting unsolicited adverse events (AEs)",
   "description": "An unsolicited AE is an AE that was either not included in the list of solicited events or could be included in the list of solicited events but with an onset outside the specified period of follow-up for solicited events.",
   "timeFrame": "Day 1 (post-dose) to Day 43"
  },
  {
   "measure": "Percentage of participants reporting medically attended AEs (MAAE)",
   "description": "A MAAE is an AE for which the participant received medical attention including any symptom or illness requiring hospitalization, or an emergency room visit, or visit to/by a healthcare professional.",
   "timeFrame": "Day 1 (post-dose) to Day 181 (study end)"
  },
  {
   "measure": "Percentage of participants reporting serious adverse events (SAEs)",
   "description": "A SAE is an AE which results in death, is life-threatening, requires inpatient hospitalization or prolongation of existing hospitalization, results in disability/incapacity, or other situations that are considered serious per medical or scientific judgment.",
   "timeFrame": "Day 1 (post-dose) to Day 181 (study end)"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Participant's parent(s)/Legally acceptable representatives (LAR\\[s\\]), who, in the opinion of the investigator, can and will comply with the requirements of the protocol (e.g., completion of the eDiaries, return for follow-up visits).\n* Written or witnessed/thumb printed informed consent obtained from the participant's parent(s)/LAR(s) prior to performance of any study-specific procedure.\n* Healthy participants as established by medical history and clinical examination before entering the study.\n* A male or female between, and including, 12 to 15 months of age (i.e., from the day of 1 year birthday until the day before 16 months of age) at the time of the administration of study interventions.\n* Only for children in countries where PCV is recommended at 12 to 15 months of age as per national immunization schedule and provided as part of the study interventions: participant who previously received the primary series of PCV in the first year of life with last dose at least 60 days prior to study entry.\n\nExclusion Criteria:\n\n* History of any reaction or hypersensitivity likely to be exacerbated by any component of the study interventions.\n* Any confirmed or suspected immunosuppressive or immunodeficient condition, based on medical history and physical examination (no laboratory testing required).\n* Hypersensitivity to latex.\n* Recurrent history of uncontrolled neurological disorders or seizures.\n* History of varicella disease.\n* Active untreated tuberculosis\n* Any other clinical condition that, in the opinion of the investigator, might pose additional risk to the participant due to participation in the study.\n* Use of any investigational or non-registered product (drug, vaccine or invasive medical device) other than the study interventions during the period beginning 30 days before the dose of study interventions administration (Day -29 to Day 1), or their planned use during the study period.\n* Planned administration of a vaccine in the period starting 30 days before the dose and ending 43 days after the dose of study interventions administration (Visit 2), with the exception of inactivated influenza vaccine which may be given at any time during the study and administered at a different location than the study interventions. Any other age-appropriate vaccine may be given starting at Visit 2 and anytime thereafter.\n* Chronic administration of immune-modifying drugs (defined as more than 14 consecutive days in total) and/or planned use of long-acting immune modifying treatments at any time up to the end of the study.\n\n  * Up to 90 days prior to the study intervention administration:\n\n    * For corticosteroids, this will mean prednisone equivalent \\>= 0.5 mg/kg/day with maximum of 20 mg/day for pediatric participants. Inhaled and topical steroids are allowed.\n    * Administration of immunoglobulins and/or any blood products or plasma derivatives.\n  * Up to 180 days prior to study interventions administration: long acting immune modifying drugs including among others immunotherapy (e.g., tumor necrosis factor-inhibitors), monoclonal antibodies (except the ones not interfering with the immune response to the study vaccines, e.g., nirsevimab), antitumoral medication.\n* Previous vaccination against measles, mumps, and rubella.\n* Previous vaccination against hepatitis A virus.\n* Previous vaccination against varicella virus.\n* Only for children in countries where PCV is recommended at 12 to 15 months of age as per national immunization schedule and provided as part of the study interventions, participant who previously received a booster dose of any PCV.\n* Concurrently participating in another clinical study, at any time during the study period, in which the participant has been or will be exposed to an investigational or a non-investigational intervention (drug/invasive medical device).\n* Child in care.\n* Any study personnel's immediate dependents, family, or household members.\n* Participants with the following high-risk individuals in their household:\n\n  * Immunocompromised individuals.\n  * Pregnant women without documented history of varicella.\n  * Newborn infants of mothers without documented history of varicella.\n  * Newborn infants born less than (\\<) 28 weeks of gestation.",
