  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 800,
 "briefSummary": "The primary purpose of this phase 3b study is to assess the efficacy of a modified regimen of ublituximab in participants with relapsing multiple sclerosis (RMS) as measured by T1 Gadolinium (Gd)-enhancing lesions in Part A; PK in Part B along with efficacy of ublituximab as measured by T1 Gd-enhancing lesions in participants who had a suboptimal experience on prior anti-CD20 therapy in Part C. The study consists of 3 parts: Part A is single-armed and open-label, Part B is randomized, double-blind, placebo-controlled, and Part C is single-armed and open-label.",
 "arms": [
  {
   "label": "Part A: Ublituximab",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive a modified regimen of ublituximab including infusions on Day 1 of Week 1 (W1D1), Day 15, if applicable, and ublituximab 450 milligrams (mg) infusion at Week 24.\n\nWith Protocol Version 6.0, enrollment in Part A was closed.",
   "interventionNames": [
    "Biological: Ublituximab"
   ]
  },
  {
   "label": "Part B: Ublituximab /Placebo (Treatment Arm A)",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive 600 mg of ublituximab on W1D1 followed by a placebo infusion on Day 15 and 450 mg ublituximab infusion at Week 24.\n\nWith Protocol Version 7.0, enrollment in Part B will be closed.",
   "interventionNames": [
    "Biological: Ublituximab",
    "Drug: Placebo"
   ]
  },
  {
   "label": "Part B: Ublituximab (Treatment Arm B)",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive 150 mg of ublituximab on W1D1 followed by 450 mg on Day 15 and at Week 24.\n\nWith Protocol Version 7.0, enrollment in Part B will be closed.",
   "interventionNames": [
    "Biological: Ublituximab"
   ]
  },
  {
   "label": "Part C: Ublituximab (Treatment Arm C)",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive 150 mg of ublituximab on W1D1, followed by 450 mg on Day 15 and at Week 24.",
   "interventionNames": [
    "Biological: Ublituximab"
   ]
  }
 ],
 "interventions": [
  {
   "type": "BIOLOGICAL",
   "name": "Ublituximab",
   "description": "Administered as an intravenous (IV) infusion.",
   "armGroupLabels": [
    "Part A: Ublituximab",
    "Part B: Ublituximab (Treatment Arm B)",
    "Part B: Ublituximab /Placebo (Treatment Arm A)",
    "Part C: Ublituximab (Treatment Arm C)"
   ],
   "otherNames": [
    "TG-1101",
    "BRIUMVI"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "IV infusion",
   "armGroupLabels": [
    "Part B: Ublituximab /Placebo (Treatment Arm A)"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Part A and Part C: Percentage of Participants With no Change or Reduction in Number of T1 Gd-Enhancing Lesions From Baseline to Week 48",
   "description": "The Gd-enhancing T1 lesions will be evaluated using magnetic resonance imaging (MRI) technique.",
   "timeFrame": "Baseline up to Week 48"
  },
  {
   "measure": "Part B: Area Under the Curve Over the First 16 Weeks (AUC0-W16) of Ublituximab",
   "timeFrame": "Predose and at multiple timepoints up to Week 16"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Parts A: Percentage of Participants Free of T1 Gd-Enhancing Lesions",
   "description": "The Gd-enhancing T1 lesions will be evaluated using MRI technique.",
   "timeFrame": "Week 48"
  },
  {
   "measure": "Parts A and B: Percentage of Participants Experiencing Infusion Related Reactions (IRRs)",
   "description": "IRRs are defined as infusion related adverse events (AEs) that occur within one day of an infusion and resolve within 7 days. IRRs will be reported by investigator.",
   "timeFrame": "Up to Week 48"
  },
  {
   "measure": "Parts A: Change From Baseline in Treatment Satisfaction Questionnaire for Medication (TSQM-9) Scores",
   "description": "The TSQM-9 is a 9-item questionnaire with 3 domains: Satisfaction, convenience, and effectiveness.",
   "timeFrame": "Part A: Baseline, Week 24 and Week 48"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Diagnosis of RMS (2017 Revised McDonald criteria).\n* Participants must meet one of the following prior treatment definitions:\n\n  1. Participants naïve to treatment.\n  2. Participants previously treated with a disease modifying therapy (DMT) who have discontinued treatment prior to consent and meet the washout requirements.\n* Expanded Disability Status Scale (EDSS) score ≤ 5.5 at screening.\n* Neurologically stable for \\> 30 days prior to first dose of ublituximab.\n* Female participants of childbearing potential must consent to use a medically acceptable method of contraception from consent, throughout the study period, and for 6 months after the last dose of ublituximab.\n* Part C: participants currently treated with an anti-CD20 agent for at least 6 months and meet the washout requirements prior to W1D1.\n* Part C: Discontinuation of current anti-CD20 must be due to suboptimal experience\n\nExclusion Criteria:\n\n* History of any serious 3 Infusion Related Reaction (IRR) on prior anti-CD20 therapy.\n* Primary-progressive multiple sclerosis (PPMS) or inactive Secondary Progressive MS (SPMS).\n* Active chronic (or stable but treated with immune therapy) disease of the immune system other than MS (e.g., rheumatoid arthritis, scleroderma, Sjögren's syndrome, Crohn's disease, ulcerative colitis, etc.) or immunodeficiency syndrome (hereditary immune deficiency, drug-induced immune deficiency, etc.).\n* Current evidence or known history of clinically significant infection, including: chronic, recurrent, or ongoing active viral, bacterial, or fungal infectious disease requiring long term systemic treatment such as, but not limited to chronic urinary tract infection, chronic pulmonary infection with bronchiectasis, tuberculosis, or active hepatitis C virus (HCV).\n* Previous serious opportunistic or atypical infection.\n* Evidence of chronic active or history of hepatitis B virus (HBV) infection as evidenced by a detectable hepatitis B surface antigen (HBsAg), or positive hepatitis B core antibody (HBcAb), or chronic hepatitis C infection. Participants with positive hepatitis C virus antibody (HCV Ab) are eligible only if polymerase chain reaction (PCR) is negative for HCV ribonucleic acid (RNA).\n* History or evidence (clinical, radiological, or biomarker) of suspected or confirmed progressive multifocal leukoencephalopathy (PML).\n* Receipt of any live or live-attenuated vaccines (including vaccines for varicella-zoster virus or measles) within 4 weeks prior to first study drug administration.\n* Participants requiring treatment with intravenous immune globulin (IVIG) for decreased immunoglobulins within the 12 months prior to W1D1.\n* Any active malignancies other than adequately treated basal, squamous cell or in situ carcinoma.\n* Participants who have ever received ublituximab, alemtuzumab, cyclophosphamide, mitoxantrone, cladribine, or daclizumab (including for non-MS indications).\n\nNote: Other Inclusion/Exclusion criteria may apply.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "65 Years"
 },
 "siteCount": 51,
 "countries": [
  "United States",
