   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Combined metabolic activators",
   "description": "A total of 20g of CMA2 with strawberry aroma and colouring agent will be given. The IMP will be provided as a soluble powder packed as individual dosages in identical sachets. The powder should be dissolved in 200 ml preferably cold water before use. The powder can also be used on yoghurt or other food. The subjects will take two daily oral doses of the IMP, one dose just after breakfast and one dose just after dinner. Subjects who cannot tolerate (e.g., diarrhoea) taking full dose will be withdrawn from the study.",
   "armGroupLabels": [
    "Treatment Arm"
   ]
  },
  {
   "type": "OTHER",
