 "primaryOutcomes": [
  {
   "measure": "Absolute change from baseline in Weekly Urticaria Activity Score (UAS7) at Week 4",
   "description": "The UAS7 is the sum of the Weekly Hives Severity (HSS7) score and the Weekly Itch Severity (ISS7) score, and ranges from 0-42. Weekly scores (HSS7 and ISS7 scores) will be derived by adding up the average daily scores of the 7 days preceding the visit.",
